   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的身体破碎得令你心如刀绞，宛如一件被拆碎了的洋娃娃，只剩下散乱的丝线还在维持着身体的支撑。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_13_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
